import{_ as a,y as i,a as c,o as l,a2 as o,D as n,g as e,I as r}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Inventory Sources","description":"","frontmatter":{},"headers":[],"relativePath":"settings/inventory-source.md","filePath":"settings/inventory-source.md","lastUpdated":1789441803000}'),u={name:"settings/inventory-source.md"};function d(h,t,g,p,y,m){const s=i("ImagePopup");return l(),c("div",null,[t[4]||(t[4]=o('<h1 id="inventory-sources" tabindex="-1">Inventory Sources <a class="header-anchor" href="#inventory-sources" aria-label="Permalink to &quot;Inventory Sources&quot;">​</a></h1><p>An inventory source is a place where you keep stock, such as a warehouse or a shop. Bagisto tracks each product&#39;s quantity per source, so you can sell stock from several locations and choose where each shipment comes from.</p><p>Every store starts with one inventory source, <strong>Default</strong>.</p><h2 id="your-inventory-sources" tabindex="-1">Your inventory sources <a class="header-anchor" href="#your-inventory-sources" aria-label="Permalink to &quot;Your inventory sources&quot;">​</a></h2><p>Go to <strong>Settings &gt;&gt; Inventory Sources</strong> to see every source with its <strong>ID</strong>, <strong>Code</strong>, <strong>Name</strong>, <strong>Priority</strong> and <strong>Status</strong>. Search by code, name or priority, or use <strong>Filter</strong> to show only active or inactive sources.</p>',5)),n(s,{src:"/images/settings/inventory-sources.png",alt:"Inventory Sources grid with the Default and West Coast Warehouse sources"}),t[5]||(t[5]=e("h2",{id:"create-an-inventory-source",tabindex:"-1"},[r("Create an inventory source "),e("a",{class:"header-anchor",href:"#create-an-inventory-source","aria-label":'Permalink to "Create an inventory source"'},"​")],-1)),e("ol",null,[t[1]||(t[1]=o("<li><p>Go to <strong>Settings &gt;&gt; Inventory Sources</strong>.</p></li><li><p>Click <strong>Create Inventory Source</strong>. The <strong>Add Inventory Source</strong> page opens.</p></li><li><p>In <strong>General</strong>, enter the <strong>Code</strong> and <strong>Name</strong>, and optionally a <strong>Description</strong>.</p></li><li><p>In <strong>Contact Information</strong>, enter the <strong>Name</strong>, <strong>Email</strong> and <strong>Contact Number</strong> of the person responsible for the source, and optionally a <strong>Fax</strong>.</p></li><li><p>In <strong>Source Address</strong>, choose the <strong>Country</strong> and <strong>State</strong>.</p></li><li><p>Enter the <strong>City</strong>, <strong>Street</strong> and <strong>Postcode</strong>.</p></li><li><p>Optionally, in <strong>Settings</strong>, enter the <strong>Latitude</strong>, <strong>Longitude</strong> and <strong>Priority</strong>.</p></li><li><p>Switch <strong>Status</strong> on.</p></li>",8)),e("li",null,[t[0]||(t[0]=e("p",null,[r("Click "),e("strong",null,"Save Inventory Sources"),r(".")],-1)),n(s,{src:"/images/settings/create-inventory-source.png",alt:"Add Inventory Source page filled in for an East Coast Warehouse"})])]),t[6]||(t[6]=o('<p>The message <em>Inventory Source Created Successfully</em> appears and the new source is listed.</p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>A unique code for the source, such as <code>east_coast_warehouse</code>. Use at least two characters: start with a letter, then letters, numbers or underscores.</td></tr><tr><td><strong>Name</strong></td><td>The name of the source, such as <strong>East Coast Warehouse</strong>.</td></tr><tr><td><strong>Description</strong></td><td>Optional notes about the source.</td></tr><tr><td><strong>Contact Information</strong></td><td>The contact person&#39;s <strong>Name</strong>, <strong>Email</strong> and <strong>Contact Number</strong>. The contact number can have only digits, with an optional <code>+</code> at the start. <strong>Fax</strong> is optional. When <strong>Send a notification e-mail to the inventory source after creating a shipment</strong> is on under <a href="./../configure/notifications.html">Configure &gt;&gt; Email &gt;&gt; Notifications</a>, this <strong>Email</strong> gets an email for each shipment from the source.</td></tr><tr><td><strong>Source Address</strong></td><td>The full address of the source. Every address field is required. <strong>State</strong> is a list for countries that have one, and a text box for others. <strong>Street</strong> can be up to 60 characters of letters, numbers, spaces and <code>&#39; - , ( )</code>; dots, slashes and <code>#</code> aren&#39;t accepted. <strong>Postcode</strong> is at least two letters, numbers, spaces or hyphens, and starts and ends with a letter or number.</td></tr><tr><td><strong>Latitude</strong> and <strong>Longitude</strong></td><td>Optional map coordinates of the source, such as <code>40.7033</code> and <code>-74.0170</code>. Latitude is between -90 and 90, longitude between -180 and 180.</td></tr><tr><td><strong>Priority</strong></td><td>An optional whole number shown in the grid to help you rank your sources. It doesn&#39;t change which source stock is sold or shipped from. If you leave it empty, <code>0</code> is saved.</td></tr><tr><td><strong>Status</strong></td><td>Turn on to use the source. It&#39;s off until you switch it on.</td></tr></tbody></table><h3 id="what-an-inactive-source-means" tabindex="-1">What an inactive source means <a class="header-anchor" href="#what-an-inactive-source-means" aria-label="Permalink to &quot;What an inactive source means&quot;">​</a></h3><p>When <strong>Status</strong> is off, the source isn&#39;t listed on product pages or when you edit a channel. Its stock stops counting as available for sale once each product&#39;s stock is updated, for example when you save the product.</p><p>If you save a channel while one of its sources is inactive, the source is removed from the channel. After you switch the source back on, select it on the channel again.</p><h2 id="sell-a-source-s-stock-on-a-channel" tabindex="-1">Sell a source&#39;s stock on a channel <a class="header-anchor" href="#sell-a-source-s-stock-on-a-channel" aria-label="Permalink to &quot;Sell a source&#39;s stock on a channel&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Channels</strong>.</li><li>Click the edit icon of the channel.</li><li>In <strong>General</strong>, select the source under <strong>Inventory Sources</strong>. You can select several sources.</li><li>Click <strong>Save Channel</strong>.</li></ol><p>A product&#39;s quantity available for sale on a channel is its stock at that channel&#39;s active sources, minus the quantity already ordered but not shipped.</p><h2 id="set-a-product-s-stock-per-source" tabindex="-1">Set a product&#39;s stock per source <a class="header-anchor" href="#set-a-product-s-stock-per-source" aria-label="Permalink to &quot;Set a product&#39;s stock per source&quot;">​</a></h2><p>Simple and virtual products have an <strong>Inventories</strong> section; other product types don&#39;t.</p>',10)),e("ol",null,[t[3]||(t[3]=o("<li><p>Go to <strong>Catalog &gt;&gt; Products</strong>.</p></li><li><p>Open the product.</p></li><li><p>In <strong>Inventories</strong>, check that <strong>Manage Stock</strong> is on. The quantity for each source appears only when it is.</p></li><li><p>Enter the quantity held at each source. Every active source is listed.</p></li>",4)),e("li",null,[t[2]||(t[2]=e("p",null,[r("Click "),e("strong",null,"Save Product"),r(".")],-1)),n(s,{src:"/images/settings/product-inventory.png",alt:"Inventories section of a product with a quantity for each inventory source"})])]),t[7]||(t[7]=o('<p><strong>Pending Ordered Qty</strong> is the quantity that has been ordered but not shipped yet. It is taken from the source&#39;s stock when the order is shipped, and becomes available for sale again if the order is canceled.</p><p>Virtual products aren&#39;t shipped. Their stock is taken when the order is invoiced, starting with the channel&#39;s source that has the most stock.</p><h2 id="ship-from-a-source" tabindex="-1">Ship from a source <a class="header-anchor" href="#ship-from-a-source" aria-label="Permalink to &quot;Ship from a source&quot;">​</a></h2><p>When you <a href="./../orders/create-shipment.html">create a shipment</a>, choose the <strong>Source</strong> the items ship from. Bagisto doesn&#39;t choose a source for you. The shipment form shows the <strong>Qty. Available</strong> at that source, and you enter the <strong>Qty. To Ship</strong>. It can&#39;t be more than the quantity left to ship or the stock at that source; otherwise <em>Qty. Invalid</em> appears when you save.</p><h2 id="edit-or-delete-an-inventory-source" tabindex="-1">Edit or delete an inventory source <a class="header-anchor" href="#edit-or-delete-an-inventory-source" aria-label="Permalink to &quot;Edit or delete an inventory source&quot;">​</a></h2><p>To edit a source:</p><ol><li>Go to <strong>Settings &gt;&gt; Inventory Sources</strong>.</li><li>Click the edit icon of the source. The <strong>Edit Inventory Sources</strong> page opens.</li><li>Make your changes.</li><li>Click <strong>Save Inventory Sources</strong>.</li></ol><p>The message <em>Inventory Sources Updated Successfully</em> appears.</p><p>To remove a source:</p><ol><li>Go to <strong>Settings &gt;&gt; Inventory Sources</strong>.</li><li>Click the delete icon of the source.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><ul><li>A store must keep at least one inventory source.</li><li>Before you delete a source, make sure each channel that uses it has another source. A channel left with no source can&#39;t be saved until you add one.</li><li>Deleting a source also deletes the stock recorded at it for every product, and removes it from your channels. Shipments already made from it are kept.</li></ul>',11))])}const S=a(u,[["render",d]]);export{f as __pageData,S as default};
